import { configure } from 'enzyme';
import Adapter from 'enzyme-adapter-react-16';

configure({ adapter: new Adapter() });

export const INCREMENT = (amount) => ({
    type: 'INCREMENT',
    payload: amount,
});

export const DECREMENT = (amount) => ({
    type: 'DECREMENT',
    payload: amount,
});

